-- Name: mdm_device_launcher_version(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mdm_device_launcher_version(launcherapppkg text, device_info text) RETURNS text
    LANGUAGE plpgsql
    AS $$
            DECLARE
            deviceApps    json;
            DECLARE i      INT;
            DECLARE count  INT;
            DECLARE app json;
            BEGIN
            IF launcherAppPkg IS NULL THEN
            RETURN NULL;
            END IF;

            IF device_info IS NULL THEN
            RETURN NULL;
            END IF;

            deviceApps = device_info::json -> 'applications';
            count = json_array_length(deviceApps);

            FOR i IN 1 .. count
            LOOP
            app = deviceApps ->> (i - 1);
            IF (app ->> 'pkg') = launcherAppPkg THEN
            RETURN app ->> 'version';
            END IF;
            END LOOP;

            RETURN NULL;
            END
            $$;


