--
-- Name: mdm_refresh_latest_version(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mdm_refresh_latest_version() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
            DECLARE
            affected INTEGER;
            BEGIN
            IF (TG_OP = 'DELETE') THEN
            affected := OLD.applicationId;
            ELSE
            affected := NEW.applicationId;
            END IF;

            UPDATE applications
            SET latestVersion = (
            SELECT apv.id
            FROM applicationVersions apv
            WHERE apv.applicationId = affected
            ORDER BY mdm_app_version_comparison_index(apv.version) DESC, apv.id DESC
            LIMIT 1)
            WHERE id = affected;

            IF (TG_OP = 'UPDATE' AND OLD.applicationId IS DISTINCT FROM NEW.applicationId) THEN
            UPDATE applications
            SET latestVersion = (
            SELECT apv.id
            FROM applicationVersions apv
            WHERE apv.applicationId = OLD.applicationId
            ORDER BY mdm_app_version_comparison_index(apv.version) DESC, apv.id DESC
            LIMIT 1)
            WHERE id = OLD.applicationId;
            END IF;

            IF (TG_OP = 'DELETE') THEN
            RETURN OLD;
            END IF;
            RETURN NEW;
            END;
            $$;


--
-- Name: mdm_resolve_device_property(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mdm_resolve_device_property(server_data text, device_data text) RETURNS text
    LANGUAGE plpgsql
    AS $$
            BEGIN
            server_data = COALESCE(server_data, '');
            device_data = COALESCE(device_data, '');

            IF (server_data = device_data) THEN
            RETURN server_data;
            END IF;

            IF LENGTH(device_data) > 0 THEN
            RETURN device_data;
            END IF;

            RETURN server_data;
            END
            $$;


